import{_ as n,a8 as o,o as i,c as r,ah as d,K as a}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const f=JSON.parse('{"title":"本地环境工具链坑（已验证）","description":"","frontmatter":{"type":"lesson","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["环境","工具链","python","SkillHub","沙箱","踩坑"]},"headers":[],"relativePath":"vault/Memory/Lessons/本地环境工具链坑.md","filePath":"vault/Memory/Lessons/本地环境工具链坑.md","lastUpdated":1789374053000}'),s={name:"vault/Memory/Lessons/本地环境工具链坑.md"};function c(h,e,u,m,p,g){const l=o("NolebaseGitContributors"),t=o("NolebaseGitChangelog");return i(),r("div",null,[e[0]||(e[0]=d('<h1 id="本地环境工具链坑-已验证" tabindex="-1">本地环境工具链坑（已验证） <a class="header-anchor" href="#本地环境工具链坑-已验证" aria-label="Permalink to “本地环境工具链坑（已验证）”">​</a></h1><h2 id="系统-python3-是坏的-windows-商店残桩" tabindex="-1">系统 python3 是坏的 Windows 商店残桩 <a class="header-anchor" href="#系统-python3-是坏的-windows-商店残桩" aria-label="Permalink to “系统 python3 是坏的 Windows 商店残桩”">​</a></h2><p>路径在 <code>C:/Users/stars/AppData/Local/Microsoft/WindowsApps/python3</code> 但运行失败。已创建垫片 <code>~/.local/bin/python3</code> 指向受管 Python <code>C:/Users/stars/.workbuddy/binaries/python/versions/3.13.12/python.exe</code>。</p><h2 id="skillhub-cli-已装" tabindex="-1">SkillHub CLI 已装 <a class="header-anchor" href="#skillhub-cli-已装" aria-label="Permalink to “SkillHub CLI 已装”">​</a></h2><ul><li>版本 v2026.8.5，本体在 <code>~/.skillhub/</code>，命令 wrapper 在 <code>~/.local/bin/skillhub</code>（同样指向受管 Python）。</li><li>用法：<code>skillhub search &lt;词&gt;</code> / <code>skillhub install &lt;skill&gt; --namespace &lt;ns&gt; --dir ~/.workbuddy/skills</code>。</li><li><code>~/.local/bin</code> 需在当前 shell 的 PATH 中。</li></ul><h2 id="网络注意" tabindex="-1">网络注意 <a class="header-anchor" href="#网络注意" aria-label="Permalink to “网络注意”">​</a></h2><ul><li>该环境对大体积外部下载会截断（curl write error），必要时用 HTTP Range 分块下载再拼接。</li><li><code>api.skillhub.cn</code> 偶发瞬时 DNS 失败，重试即可。</li></ul><h2 id="e-盘直写陷阱-2026-09-09-实测" tabindex="-1">E: 盘直写陷阱（2026-09-09 实测） <a class="header-anchor" href="#e-盘直写陷阱-2026-09-09-实测" aria-label="Permalink to “E: 盘直写陷阱（2026-09-09 实测）”">​</a></h2><ul><li>沙箱模式下对 <code>/e/...</code>（工作区外）的写入会被虚拟化/错位——git clone 到 <code>/e/Github/...</code> 会把文件实际写到 <code>E:\\e\\Github\\...</code>（MSYS 路径前缀被再拼接一层），且沙箱外 <code>ls</code> 看不见、<code>git</code> 却报 &quot;already exists&quot;。</li><li>解法：① 工作区外写文件用非沙箱模式；② 已产生的幽灵目录可从中抢救内容后整体删除；③ zip 兜底下载 <code>codeload.github.com</code>（18MB 可一次成功，直连 git 端点反而常 Connection reset）。</li><li>Git Bash 中 <code>git -C /e/...</code> 可能报 &quot;cannot change to&quot;，改用 <code>cd &lt;path&gt; &amp;&amp; git</code> 即正常。</li></ul><h2 id="intel-arc-驱动安装失败-错误-1001" tabindex="-1">Intel Arc 驱动安装失败（错误 1001） <a class="header-anchor" href="#intel-arc-驱动安装失败-错误-1001" aria-label="Permalink to “Intel Arc 驱动安装失败（错误 1001）”">​</a></h2><ul><li>卸载重装 / 官方助手都报 <strong>错误代码 1001</strong>。解法：从 Intel 官网直接下完整包 <code>gfx_win_101.8991.exe</code> <strong>手动全新安装</strong>（不要走增量更新）。</li><li>NPU 初始化后模型默认落在 <code>E:\\data\\models</code>（如 Qwen3 8B INT4 CW OpenVINO）。</li></ul><h2 id="npu-本地模型有-prompt-长度上限" tabindex="-1">NPU 本地模型有 prompt 长度上限 <a class="header-anchor" href="#npu-本地模型有-prompt-长度上限" aria-label="Permalink to “NPU 本地模型有 prompt 长度上限”">​</a></h2><ul><li>端侧上下文上限默认 <strong>1024 tokens</strong>，超限触发 <strong>OpenVINO GenAI 错误 10000</strong>（不是模型坏了，是上下文被截断）。</li><li>解法：把端侧上下文上限调大（实测调到 40960 后恢复正常，模型连通性测试通过）。</li></ul><h2 id="windows-保留设备名文件-nul-等-删不掉" tabindex="-1">Windows 保留设备名文件（<code>nul</code> 等）删不掉 <a class="header-anchor" href="#windows-保留设备名文件-nul-等-删不掉" aria-label="Permalink to “Windows 保留设备名文件（nul 等）删不掉”">​</a></h2><ul><li>脚本里 <code>&gt; nul</code> 重定向写错会在当前目录<strong>真的创建出名为 <code>nul</code> 的文件</strong>，常规 <code>rm</code>/资源管理器/脚本均无法删除（保留设备名）。</li><li>解法：用 <code>\\\\?\\</code> 扩展路径前缀绕过设备名限制删除（与长路径删除同一招）。</li></ul><h2 id="git-bash-find-exec-md5sum-大量文件时报-environment-too-large-大量文件时报-environment-too-large" tabindex="-1">Git-Bash <code>find -exec md5sum</code> 大量文件时报 environment too large 大量文件时报 environment too large <a class="header-anchor" href="#git-bash-find-exec-md5sum-大量文件时报-environment-too-large-大量文件时报-environment-too-large" aria-label="Permalink to “Git-Bash find -exec md5sum 大量文件时报 environment too large 大量文件时报 environment too large”">​</a></h2><ul><li>本机 Git-Bash 下对几百个文件做 <code>find ... -exec md5sum {} \\;</code> 会触发 <strong>&quot;environment too large for exec()&quot;</strong>（MSYS 的 exec 环境大小限制），导致哈希脚本<strong>空转</strong>——哈希文件写出为空、孤儿判定误为 0，校验实际未生效（依赖的是上一轮已完成的哈希结论，删除动作本身正确但有盲区）。</li><li><strong>正解</strong>：在此环境做大量文件哈希 / 删除前校验，直接用 <strong>Python <code>os.walk</code> + <code>hashlib</code></strong>，不要用 <code>find -exec md5sum</code>。Python 走受管 venv（如 <code>envs/default/Scripts/python.exe</code>）即可稳定跑完。</li></ul>',17)),a(l),a(t)])}const k=n(s,[["render",c]]);export{f as __pageData,k as default};
